<div class="page-title"><div><em>ADMINISTRATION</em><h1>Admin users</h1><p>Manage the administrators who can access this portal.</p></div><button class="btn" data-modal="admin-modal">+ Add administrator</button></div><section class="panel"><div class="data-table"><div class="tr th"><span>Administrator</span><span>Username</span><span>Email</span><span>Last login</span><span>Status</span></div><?php foreach($admins as $a):?><div class="tr"><span class="name"><i><?=initials($a['first_name'].' '.$a['last_name'])?></i><b><?=html_escape($a['first_name'].' '.$a['last_name'])?></b></span><strong><?=html_escape($a['username'])?></strong><span><?=html_escape($a['email'])?></span><span><?=$a['last_login_at']?date('M j, g:i a',strtotime($a['last_login_at'])):'Never'?></span><span class="<?=status_class($a['status'])?>"><?=ucfirst($a['status'])?></span></div><?php endforeach?></div></section>
<dialog id="admin-modal"><div class="dialog-head"><h2>Add administrator</h2><button data-close>×</button></div><?=form_open('admin/admin_users')?><div class="form-grid"><div><label>First name</label><input name="first_name" required></div><div><label>Last name</label><input name="last_name" required></div></div><label>Username</label><input name="username" required><label>Email</label><input name="email" type="email" required><label>Temporary password</label><input name="password" type="password" minlength="8" required><button class="btn wide">Create administrator</button></form></dialog>
